<script setup>
import {ref} from 'vue';import {getOrder,statusLabels,statusOrder} from '../mockStore'
const code=ref('MC-1047'),data=ref(null),error=ref('')
function search(){error.value='';data.value=getOrder(code.value.trim());if(!data.value)error.value='No fue posible encontrar una reparación con el código ingresado. Revisa el código e inténtalo nuevamente.'}
function stateFor(s){if(!data.value)return'';const current=statusOrder.indexOf(data.value.status),i=statusOrder.indexOf(s);if(data.value.status==='REJECTED')return s==='RECEIVED'?'done':'';return i<current?'done':i===current?'current':''}
</script>
<template><div class="min-vh-100 py-4 px-3" style="background:#eef4f8"><div class="mobile-public"><div class="d-flex justify-content-between align-items-center mb-4"><div class="fw-bold fs-5" style="color:var(--mc-navy)"><i class="bi bi-tools me-2"></i>MARTINI CELL</div><router-link to="/login" class="small">Acceso interno</router-link></div><div class="mc-card p-4 mb-3"><h2 class="h4 fw-bold">Consulta tu reparación</h2><p class="text-muted">Ingresa el código entregado cuando dejaste tu equipo.</p><form @submit.prevent="search" class="d-flex gap-2"><input v-model="code" class="form-control" placeholder="Ej. MC-1047" required><button class="btn btn-primary">Consultar</button></form><div v-if="error" class="alert alert-warning mt-3 mb-0">{{error}}</div><div class="small text-muted mt-3">Código demo sugerido: <strong>MC-1047</strong></div></div><div v-if="data" class="mc-card p-4"><div class="small text-muted">ORDEN {{data.code}}</div><div class="mt-3 small text-muted">Estado actual</div><div class="fs-4 fw-bold text-primary">{{statusLabels[data.status]}}</div><div class="small text-muted mt-1">Última actualización: {{new Date(data.updated_at).toLocaleString('es-CL')}}</div><hr><h6>Progreso</h6><div v-if="data.status==='REJECTED'" class="alert alert-secondary">La reparación fue registrada como no reparada/rechazada.</div><div v-else><div v-for="s in statusOrder" class="progress-step" :class="stateFor(s)"><div class="dot"><i v-if="stateFor(s)==='done'" class="bi bi-check"></i><i v-else-if="stateFor(s)==='current'" class="bi bi-dot"></i></div><div>{{statusLabels[s]}}</div></div></div><div class="alert alert-light border small mt-4 mb-0">Para más información, contacta directamente a Martini Cell.</div></div><p class="text-center text-muted small mt-4">La consulta pública no muestra datos personales, fotografías, costos internos ni índice de viabilidad.</p></div></div></template>
